=Analyze this App Store review:

**Title:** {{ $json.title }}
**Rating:** {{ $json.rating }}/5 stars
**Review Text:** {{ $json.body }}
**Territory:** {{ $json.territory }}

Return ONLY the JSON object described in the system message. `category` must be exactly one of the 11 cluster names (verbatim string).

parameters.jsCode:
// Extract just the data array from the wrapper
const input = $input.first().json;

// Handle if input is array or object
const dataArray = Array.isArray(input) ? input[0].data : input.data;

// Return each review as a separate item
return dataArray.map(review => ({
  json: {
    reviewId: review.id,
    type: review.type,
    rating: review.attributes.rating,
    title: review.attributes.title,
    body: review.attributes.body,
    reviewerNickname: review.attributes.reviewerNickname,
    createdDate: review.attributes.createdDate,
    territory: review.attributes.territory,
    hasResponse: review.relationships?.response?.data !== null,
    rawData: review
  }
}));

// Parse OpenAI sentiment analysis response
const aiResponse = $input.first().json;
const loopData = $('Loop Over Items').first().json;

try {
  let content = aiResponse.content || aiResponse.message?.content || aiResponse.choices?.[0]?.message?.content;

  if (!content) {
    throw new Error('No content found in OpenAI response');
  }

  // Remove markdown formatting if present
  // Gemini returns the text under content.parts[0].text
  const contentText = content.parts[0].text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const analysis = JSON.parse(contentText);
  const ALLOWED = new Set(["Technical Playback & Stability Issues", "Account & Subscription Management Difficulties", "Advertising Experience Issues", "Content Gaps, Quality & Relevance", "Age Verification & Data Privacy Concerns", "Poor User Interface & Navigation (UX)", "Value Perception & Monetization Critique", "General Dissatisfaction & Non-Specific Feedback", "N/A", "Positives Feedback", "Lacking Customer Support"]);
  const category = (analysis && typeof analysis.category === 'string' && ALLOWED.has(analysis.category.trim())) ? analysis.category.trim() : 'N/A';


  // Return complete data structure with review info and analysis
  return [{
    json: {
      review_id: loopData.reviewId,
      review_title: loopData.title,
      review_body: loopData.body,
      review_rating: loopData.rating,
      review_date: loopData.createdDate,
      reviewer_nickname: loopData.reviewerNickname,
      territory: loopData.territory,
      sentiment: analysis.sentiment,
      category: category,
      key_issues: analysis.key_issues,
      urgency: analysis.urgency,
      summary: analysis.summary,
      response_tone: analysis.response_tone,
      action_required: analysis.action_required,
      customer_emotion: analysis.customer_emotion
    }
  }];
} catch (error) {
  return [{
    json: {
      error: 'Failed to parse sentiment analysis',
      details: error.message,
      raw_response: aiResponse,
      loop_data: loopData
    }
  }];
}

