  }
}));

const crypto = require('crypto');

// Stable, PII-free id: hash the review's own timestamp + platform id + reviewer name.
// The reviewer name is used only to build the hash and is NOT stored.
return $input.all().map(item => {
  const d = item.json;
  const id = crypto
    .createHash('sha256')
    .update(`${d.review_date}|${d.review_id}|${d.reviewer_nickname ?? ''}`)
    .digest('hex')
    .substring(0, 32);

  const key_issues = (d.key_issues && typeof d.key_issues === 'object')
    ? JSON.stringify(d.key_issues)
    : (d.key_issues ?? null);

  return { json: {
    id,
    platform: 'apple_app_store',
    review_id: d.review_id,
    review_title: d.review_title ?? null,
    review_body: d.review_body ?? null,
    original_text: null,
    rating: d.review_rating ?? null,
    review_date: d.review_date ?? null,
    territory: d.territory ?? null,
    device: null,
    os_version: null,
    app_version: null,
    sentiment: d.sentiment ?? null,
    category: d.category ?? null,
    key_issues,
    urgency: d.urgency ?? null,
    summary: d.summary ?? null,
    response_tone: d.response_tone ?? null,
    action_required: d.action_required ?? null,
    customer_emotion: d.customer_emotion ?? null,
    device_context: null,
    analyzed_at: new Date().toISOString()
  }};
});

const crypto = require('crypto');

// Stable, PII-free id: hash the review's own timestamp + platform id + reviewer name.
// The reviewer name is used only to build the hash and is NOT stored.
return $input.all().map(item => {
  const d = item.json;

  // Convert last_modified {seconds, nanos} → ISO timestamp string
  const seconds = parseInt(d.last_modified.seconds);
  const nanos = d.last_modified.nanos || 0;
  const review_date = new Date(seconds * 1000 + nanos / 1000000).toISOString();

  const id = crypto
    .createHash('sha256')
    .update(`${review_date}|${d.review_id}|${d.author_name ?? ''}`)
    .digest('hex')
    .substring(0, 32);

  const key_issues = (d.key_issues && typeof d.key_issues === 'object')
    ? JSON.stringify(d.key_issues)
    : (d.key_issues ?? null);

  return { json: {
    id,
    platform: 'google_play',
    review_id: d.review_id,
    review_title: null,
    review_body: d.review_text ?? null,
    original_text: d.original_text ?? null,
    rating: d.rating ?? null,
    review_date,
    territory: null,
    device: d.device ?? null,
    os_version: d.android_version ?? null,
    app_version: d.app_version ?? null,
    sentiment: d.sentiment ?? null,
    category: d.category ?? null,
    key_issues,
    urgency: d.urgency ?? null,
    summary: d.summary ?? null,
    response_tone: d.response_tone ?? null,
    action_required: d.action_required ?? null,
    customer_emotion: d.customer_emotion ?? null,
    device_context: d.device_context ?? null,
    analyzed_at: new Date().toISOString()
  }};
});

// Existing stable ids already in Snowflake (whole set for this platform, no time window)
const existingIds = new Set(
  $input.all().map(item => item.json.id)
);

// The transformed records from the Add Unique ID node
const newRecords = $('Add Unique ID').all();

// Keep only rows whose stable id is not already stored (also dedups within the batch)
const toInsert = newRecords.filter(item => !existingIds.has(item.json.id));

if (toInsert.length === 0) {
  // Nothing new -> downstream insert has nothing to process
  return [];
}

return toInsert;

// Existing stable ids already in Snowflake (whole set for this platform, no time window)
const existingIds = new Set(
  $input.all().map(item => item.json.id)
);

// The transformed records from the Add Unique ID - Android node
const newRecords = $('Add Unique ID - Android').all();

// Keep only rows whose stable id is not already stored (also dedups within the batch)
const toInsert = newRecords.filter(item => !existingIds.has(item.json.id));

if (toInsert.length === 0) {
  // Nothing new -> downstream insert has nothing to process
  return [];
}

return toInsert;

const jwt = require('jsonwebtoken');

// Load credentials from n8n environment variables
const issuerID = $env.APPLE_ISSUER_ID;
const keyID = $env.APPLE_KEY_ID;
const privateKey = $env.APPLE_PRIVATE_KEY;

// Validate that all required environment variables are set
if (!issuerID || !keyID || !privateKey) {
  throw new Error('Missing required environment variables: APPLE_ISSUER_ID, APPLE_KEY_ID, or APPLE_PRIVATE_KEY');
}

const token = jwt.sign(
  {
    iss: issuerID,
    exp: Math.floor(Date.now() / 1000) + (20 * 60),
    aud: 'appstoreconnect-v1'
  },
  privateKey,
  {
    algorithm: 'ES256',
    header: {
      alg: 'ES256',
      kid: keyID,
      typ: 'JWT'
    }
  }
);

return [{ json: { token } }];

const jwt = require('jsonwebtoken');

// === CONFIG: hardcoded list of Usersnap survey (project) IDs to ingest ===
const SURVEYS = [
  { project_id: 'REPLACE_PROJECT_ID_1', survey_name: 'Web feedback survey' },
  {project_id:'REPLACE_PROJECT_ID_2', survey_name:'NPS email survey'},
  {
    project_id:'REPLACE_PROJECT_ID_3', survey_name:'In-app feedback survey' 
  }
  // , { project_id: 'REPLACE_PROJECT_ID_2', survey_name: 'survey 2' }
];

const secret = $env.USERSNAP_TOKEN;
const kid = $env.USERSNAP_JWT_KID;
if (!secret || !kid) {
  throw new Error('Missing env vars: USERSNAP_TOKEN (JWT secret) and/or USERSNAP_JWT_KID (JWT ID)');
}

const now = Math.floor(Date.now() / 1000);
const token = jwt.sign(
  { iat: now, exp: now + 3600 },
  secret,
  { algorithm: 'HS256', header: { alg: 'HS256', kid: kid, typ: 'JWT' } }
);

return SURVEYS.map(s => ({ json: { project_id: s.project_id, survey_name: s.survey_name, token } }));

// Flatten Usersnap feedbacks -> one item per feedback (PII-safe, generic).
// survey_name is resolved by PROJECT_ID (robust; no pairedItem dependency).
const surveys = $('Usersnap Surveys + JWT').all();
const byProject = {};
for (const s of surveys) {
  const j = s.json || {};
  if (j.project_id != null) byProject[String(j.project_id)] = (j.survey_name ?? null);
}

function extractFeedbacks(body) {
  if (Array.isArray(body)) {
    let acc = [];
    for (const el of body) acc = acc.concat(extractFeedbacks(el));
    return acc;
  }
  if (body && typeof body === 'object') {
    if (Array.isArray(body.feedbacks)) return body.feedbacks;
    if (body.data) return extractFeedbacks(body.data);
    if (body.feedback_id) return [body];
  }
  return [];
}

const out = [];
for (const item of $input.all()) {
  const list = extractFeedbacks(item.json);
  for (const fb of list) {
    const inputs = Array.isArray(fb.ordered_inputs) ? fb.ordered_inputs : [];

    const ratingField = inputs.find(i => String(i.field_type || '').startsWith('rating'));
    const rating = ratingField ? (ratingField.numeric_value ?? ratingField.value ?? null) : null;

    const feedback_text = inputs
      .map(i => (i.text_value != null ? String(i.text_value) : ''))
      .filter(t => t.trim() !== '')
      .join('\n');

    const questions = inputs.map(i => ({
      field_id: i.field_id ?? null,
      label: i.label ?? null,
      field_type: i.field_type ?? null,
      value: i.value ?? null,
      order: i.order ?? null,
    }));

    const client = fb.client || {};
    const customData = fb.custom_data || {};

    // PII: never store email. Scrub it from the retained raw payload too.
    const scrubbed = { ...fb };
    delete scrubbed.email;

    const projectId = fb.project_id ?? null;
    out.push({ json: {
      project_id: projectId,
      survey_name: (projectId != null ? (byProject[String(projectId)] ?? null) : null),
      feedback_id: String(fb.feedback_id ?? fb.id ?? ''),
      feedback_number: fb.feedback_number ?? null,
      public_link: fb.public_link ?? null,
      created_at: fb.created_at || null,
      updated_at: fb.updated_at || null,
      status: fb.status_type || fb.status || null,
      country: client.country_name ?? null,
      city: client.city_name ?? null,
      browser: client.browser_full_name ?? null,
      os: client.browser_os ?? null,
      page_url: client.url ?? null,
      app_version: (customData && customData.version) ? customData.version : null,
      rating,
      feedback_text: feedback_text || null,
      questions: JSON.stringify(questions),
      labels: fb.labels ? JSON.stringify(fb.labels) : null,
      raw_payload: JSON.stringify(scrubbed),
    } });
  }
}
return out;

values.content:
=Classify this YOUR_PRODUCT feedback into one cluster.

Rating (context, may be blank): {{ $json.rating }}
Feedback text:
{{ $json.feedback_text }}

Return only the JSON object.

parameters.jsCode:
const ALLOWED = new Set(["Technical Playback & Stability Issues", "Account & Subscription Management Difficulties", "Advertising Experience Issues", "Content Gaps, Quality & Relevance", "Age Verification & Data Privacy Concerns", "Poor User Interface & Navigation (UX)", "Value Perception & Monetization Critique", "General Dissatisfaction & Non-Specific Feedback", "N/A", "Positives Feedback", "Lacking Customer Support"]);

const aiResponse = $input.first().json;
const feedback = $('Loop Over Items - Usersnap').first().json;

let category = 'N/A';
try {
  const content = aiResponse.content || aiResponse.message?.content;
  let text = '';
  if (content && content.parts && content.parts[0] && typeof content.parts[0].text === 'string') {
    text = content.parts[0].text;
  } else if (typeof content === 'string') {
    text = content;
  }
  text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(text);
  if (parsed && typeof parsed.category === 'string' && ALLOWED.has(parsed.category.trim())) {
    category = parsed.category.trim();
  }
} catch (e) {
  category = 'N/A';
}

return [{ json: { ...feedback, category, categorized_at: new Date().toISOString() } }];

// Done branch: enriched feedback items (category attached in the loop).
// Emit final column order; this node is the holder Check Duplicates reads from.
return $input.all().map(item => {
  const d = item.json;
  return { json: {
    project_id: d.project_id ?? null,
    survey_name: d.survey_name ?? null,
    feedback_id: d.feedback_id ?? null,
    feedback_number: d.feedback_number ?? null,
    public_link: d.public_link ?? null,
    created_at: d.created_at ?? null,
    updated_at: d.updated_at ?? null,
    status: d.status ?? null,
    country: d.country ?? null,
    city: d.city ?? null,
    browser: d.browser ?? null,
    os: d.os ?? null,
    page_url: d.page_url ?? null,
    app_version: d.app_version ?? null,
    rating: d.rating ?? null,
    feedback_text: d.feedback_text ?? null,
    questions: d.questions ?? null,
    category: d.category ?? 'N/A',
    labels: d.labels ?? null,
    raw_payload: d.raw_payload ?? null,
    categorized_at: d.categorized_at ?? null,
  }};
});

// Existing feedback_ids already in Snowflake (whole table, no time window).
const existing = new Set($input.all().map(item => item.json.feedback_id));

// Enriched rows from the build node.
const newRecords = $('Build Usersnap Row').all();

// Keep only rows whose feedback_id is not already stored (also dedups the batch).
const toInsert = newRecords.filter(item => !existing.has(item.json.feedback_id));

if (toInsert.length === 0) return [];
return toInsert;
